#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        assert(x>=1 && y>=1 && x+y<=n);
        ops.push_back({x,y});
        vector<int> np(n);
        // last y -> front
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        // middle [x..n-y-1] -> after y
        int mid=n-y-x;
        for(int i=0;i<mid;i++) np[y+i]=p[x+i];
        // first x -> end
        for(int i=0;i<x;i++) np[y+mid+i]=p[i];
        p=np;
    };

    // Strategy: place elements 1,2,...,n into positions 0,1,...,n-1
    // For each target, find the value (target+1), move it to position target.

    for(int target=0; target<n-1; target++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        // Step 1: Move element from pos to position 0
        if(pos>0){
            // op(pos, n-pos): last (n-pos) elements start at index pos
            // element at pos goes to np[0]
            int y=n-pos;
            int x=pos;
            // x+y=n, need x+y<=n ✓, x>=1 (pos>0) ✓, y>=1 ✓
            apply(x,y);
            pos=0;
        }

        // Step 2: Move element from position 0 to position target
        if(target==0) continue; // already there

        // op(x,y): element at 0 goes to np[y + (n-y-x) + 0] = np[n-x]
        // Want n-x = target => x = n-target
        // Need y>=1, x>=1 (n-target>=1 since target<n) ✓
        // Need x+y<=n => y <= target
        // Take y=1 if target>=1
        {
            int x = n - target;
            int y = 1;
            if(x>=1 && y>=1 && x+y<=n){
                apply(x,y);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
